CREATE DATABASE IF NOT EXISTS codequest_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE codequest_db;
CREATE TABLE users(id INT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(50) NOT NULL UNIQUE,email VARCHAR(100) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,total_xp INT DEFAULT 0,player_level INT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admins(id INT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(50) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL);
CREATE TABLE missions(id INT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(100) NOT NULL,description TEXT NOT NULL,category VARCHAR(30) NOT NULL,difficulty VARCHAR(20) NOT NULL,option_a VARCHAR(255) NOT NULL,option_b VARCHAR(255) NOT NULL,option_c VARCHAR(255) NOT NULL,option_d VARCHAR(255) NOT NULL,correct_answer VARCHAR(255) NOT NULL,xp_reward INT DEFAULT 50,created_by INT,FOREIGN KEY(created_by) REFERENCES admins(id) ON DELETE SET NULL);
CREATE TABLE mission_submissions(id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL,mission_id INT NOT NULL,answer VARCHAR(255) NOT NULL,is_correct BOOLEAN DEFAULT FALSE,completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(mission_id) REFERENCES missions(id) ON DELETE CASCADE,UNIQUE KEY uq_user_mission(user_id,mission_id));
CREATE INDEX idx_users_xp ON users(total_xp);
